"""Individually read FSP documents and clearly labeled legacy merchant records."""
import pathlib,json,re,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1];D=ROOT/'data/deep-review/power-fsp';OUT={};docs=[json.loads(p.read_text()) for p in (D/'sources').glob('*.json')]
def make(id,model,source,rows,facts,patch=None,mpn='',notes=None):
 p={'identityKind':'mpn' if mpn else 'manufacturer-model','manufacturerModel':model,'mpn':mpn,'identityNote':'Identité exacte dans le document cité. '+('La référence commerciale est publiée explicitement.' if mpn else 'Aucun SKU commercial distinct n’est attribué.'),'sources':[source],'groups':[{'title':'Fiche constructeur' if source['kind']=='manufacturer' else 'Fiche marchande ancienne — confirmation constructeur absente','rows':[{'label':k,'value':str(v)} for k,v in rows.items()]}],'fieldEvidence':{k:{'value':v,'sourceURL':source['url'],'checkedAt':source['checkedAt']} for k,v in facts.items()},'patch':{'manufacturerModel':model,'detailLevel':'partial','description':'Alimentation FSP '+model+'. Données reprises du document exact cité ; aucune offre actuelle créée.','specs':[model],**(patch or {})},'offers':[],'notes':notes or []}
 if mpn:p['patch']['manufacturerPartNumber']=mpn
 OUT[id]=p;return p
def source(d,name,kind='manufacturer'):return {'name':name,'url':d.get('resolvedURL',d['url']),'checkedAt':d['checkedAt'],'kind':kind}
def main():
 # FSP branded one-page datasheet inspected visually in full; a distributor
 # hosts this original document, whose logo, contact details and SKU are explicit.
 d=next(d for d in docs if 'rosch-computer' in d['url']);assert '650W (continuous)' in d['primaryText'];s=source(d,'FSP — fiche FSP650-80EGN 90+, PDF original distribué par Rosch, page 1')
 rows={'Modèle fabricant':'FSP650-80EGN 90+','Référence commerciale':'9PA6502502','Puissance nominale continue':'650 W','Puissance de crête':'700 W','Format':'ATX / PS2','Dimensions (profondeur × largeur × hauteur)':'140 × 150 × 86 mm','Certification':'80 PLUS Gold','Rendement mesuré (charge 20 / 50 / 100 %)':'89,67 / 90,97 / 88,54 %','Entrée secteur':'90–264 V ; 10–5 A ; 47–63 Hz','Rail +12 V combiné':'600 W / 50 A, quatre rails limités chacun à 18 A','Rails +3,3 V / +5 V':'26 A chacun, 150 W combinés','Rails -12 V / +5Vsb':'0,5 A / 3,5 A, 23,5 W combinés','Connecteurs':'1 ATX 20+4 ; 1 EPS 4+4 ; 2 PCIe 6 broches ; 2 PCIe 6+2 ; 4 SATA ; 4 Molex ; 1 Floppy','Ventilateur':'Roulement à billes double ; diamètre non indiqué dans cette fiche','Protections':'OCP, OVP, UVP, OTP, OPP, SCP','Garantie annoncée sur le document':'2 ans'}
 make('import-psu-dfda1cc04099','FSP650-80EGN 90+',s,rows,{'power':650,'format':'ATX / PS2','depth':140,'width':150,'height':86,'efficiency':'80 PLUS Gold','rail12v':'600 W combinés sur +12V1/2/3/4','connectors':rows['Connecteurs'],'fan':rows['Ventilateur'],'protections':rows['Protections'],'warranty':'2 ans — logo sur le PDF constructeur'},patch={'wattage':650,'psuFormat':'ATX','depthMm':140,'widthMm':150,'heightMm':86},mpn='9PA6502502',notes=['La valeur 700 W est une crête ; la puissance continue publiée est 650 W.','Inspection visuelle du PDF : logo FSP, référence 9PA6502502, dimensions et tableau des connecteurs contrôlés.'])
 # Full FSP USA page retained through Exa because native collection is blocked.
 full=json.loads((D/'followup-full.json').read_text());text='\n'.join(b.get('text','') for b in full['result']['content']);assert '400-WATT, ATX 12V v2.2' in text and 'period of 1-Year' in text
 s={'name':'FSP Group USA — ATX400-PNT, page produit intégrale','url':'https://www.fspgroupusa.com/ecommerce/pc-psu/atx400-pnt.html','checkedAt':full['checkedAt'],'kind':'manufacturer'}
 make('import-psu-151622328ff0','ATX400-PNT',s,{'Modèle':'ATX400-PNT','Puissance annoncée':'400 W','Norme ATX':'ATX12V v2.2','Ventilateur':'120 mm, contrôle thermique','Connectique annoncée':'Alimentation Serial ATA prise en charge ; nombre non publié','Veille':'1 W','Garantie du modèle OEM':'1 an'}, {'power':400,'format':'ATX','atx':'ATX12V 2.2','fan':'120 mm, contrôle thermique','warranty':'1 an — garantie OEM explicitement indiquée'},patch={'wattage':400,'psuFormat':'ATX','fanSizeMm':120})
 presentation=json.loads((D/'vital-presentation.json').read_text());t='\n'.join(b.get('text','') for b in presentation['result']['content']);assert 'PART:PPA4001912' in t and '400-WATT TOTAL CONTINUOUS OUTPUT @ 30°C' in t
 s={'name':'FSP Group USA — présentation VITAL400, diapositives 3, 5 et 6','url':presentation['url'],'checkedAt':presentation['checkedAt'],'kind':'manufacturer'}
 rows={'Référence commerciale':'PPA4001912','Puissance continue':'400 W à 30 °C','Normes':'ATX 2.31 / EPS 2.92','Certification et rendement':'80 PLUS, >80 %','Ventilateur':'120 mm','Modularité':'Câbles fixes (MODULAR CABLE: N/A)','Dimensions (largeur × profondeur × hauteur)':'5.90 × 5.51 × 3.38 pouces — dimensions de l’unité','Masse':'3.60 lb','Connecteurs':'ATX 20+4 ; P4 4+4 ; 3 Molex ; 1 FDD ; 4 SATA ; 1 PCIe 6+2','Rails de sortie':'+3,3 V 24 A ; +5 V 23 A ; +12V1 17 A ; +12V2 15 A ; -12 V 0,5 A ; +5Vsb 2,5 A','Protections':'OCP, OVP, UVP, SCP, OPP','MTBF':'100 000 heures, conditions typiques','PFC':'Actif, facteur de puissance ≥0,99','Garantie':'3 ans'}
 make('import-psu-53c110cc9ed9','VITAL 400',s,rows,{'power':'400 W continus à 30 °C','format':'ATX','atx':'ATX 2.31','efficiency':'80 PLUS >80 %','modularity':'Câbles fixes','height':'3.38 in','width':'5.90 in','depth':'5.51 in','connectors':rows['Connecteurs'],'fan':'120 mm','protections':rows['Protections'],'warranty':'3 ans'},patch={'wattage':400,'psuFormat':'ATX','fanSizeMm':120},mpn='PPA4001912',notes=['Présentation signée FSP Group USA avec référence PPA4001912 et coordonnées fabricant. Les dimensions d’emballage ne sont pas attribuées à l’alimentation.'])
 # The old merchant tables are useful but not relabeled as manufacturer proof.
 for id,cap in [('import-psu-8033bbbfd4e0',450),('import-psu-18b8aa77c8fb',500)]:
  d=next(d for d in docs if f'newegg.com/fsp-group-saga-{cap}r-' in d['url']);rows={r[0]:r[1] for tab in d['tables'] for r in tab if len(r)==2};assert rows['Model']==f'SAGA+ {cap}R';s=source(d,'Newegg — fiche historique exacte SAGA+ '+str(cap)+'R','retailer');facts={'format':'ATX','atx':rows['Type'],'fan':rows['Fans'],'efficiency':rows['Efficiency'],'connectors':rows['Connectors'],'warranty':'3 ans — garantie marchande américaine'}
  if rows.get('Modular')=='No':facts['modularity']='Câbles fixes'
  if rows.get('Over Voltage Protection'):facts['protections']='OVP : '+rows['Over Voltage Protection']
  p=make(id,f'SAGA+ {cap}R',s,rows,facts,patch={'psuFormat':'ATX','fanSizeMm':120,'name':f'Group SAGA+ {cap}R · {cap} W maximum · ATX','specs':[f'{cap} W maximum annoncé',rows['Type'],'Puissance continue non documentée']},notes=['Source marchande historique : confirmation constructeur primaire encore absente.','La fiche donne une puissance maximale, pas une puissance continue ; cette valeur n’est pas utilisée comme capacité nominale vérifiée.','Les valeurs de sortie remplacées par [email protected] sur la page ne sont pas reconstituées.'])
  if cap==450:p['patch'].update(depthMm=140,widthMm=150,heightMm=86);p['fieldEvidence'].update({k:{'value':v,'sourceURL':s['url'],'checkedAt':s['checkedAt']} for k,v in {'depth':140,'width':150,'height':86}.items()})
  p['clearNominalPower']=True
 # Retailer ZEN page contradicts itself about SATA. Preserve both explicitly.
 d=next(d for d in docs if 'atxpowersupplies.com/400-' in d['url']);s=source(d,'ATXPowerSupplies — fiche exacte FSP ZEN400','retailer');t=d['primaryText'];assert 'FSP ZEN400' in t
 rows={'Puissance annoncée':'400 W','Certification':'80 PLUS Bronze','Ventilateur':'Aucun, refroidissement passif','Bruit annoncé':'0 dB','Dimensions (largeur × hauteur × profondeur)':'5.9 × 3.4 × 5.5 pouces','Connecteurs publiés':'1 ATX 20/24 ; 1 P4 ; 2 PCI Express ; 4 Molex','SATA — description':'2 prises','SATA — caractéristiques':'4 prises','Rails 12 V':'+12V1 : 14 A ; +12V2 : 13 A ; total annoncé 27 A','Autres rails':'+3,3 V : 20 A ; +5 V : 14 A ; -12 V : 0,5 A ; +5Vsb : 2,5 A','Certifications de sécurité':'cUL, CE, CB, FCC'}
 p=make('import-psu-080ab2c7872e','ZEN400',s,rows,{'power':400,'format':'ATX','efficiency':'80 PLUS Bronze','fan':'Sans ventilateur (passif)','width':'5.9 in','height':'3.4 in','depth':'5.5 in'},patch={'wattage':400,'psuFormat':'ATX','fanCount':0},notes=['Fiche marchande uniquement. Le nombre de SATA est contradictoire dans la même page (2 ou 4) et reste non résolu.'])
 p['fieldEvidence']['connectors']={'value':'2 ou 4 SATA selon la section de la même page','sourceURL':s['url'],'checkedAt':s['checkedAt'],'conflicting':True}
 # Exact old commercial listing with explicit Russian axis labels W/H/D.
 d=next(d for d in docs if 'rootnet.com.ua' in d['url']);t=d['primaryText'];assert 'EVEREST_85PLUS_800' in t and '150 x 86 x 165' in t;s=source(d,'RootNet — fiche historique EVEREST_85PLUS_800','retailer')
 rows={'Puissance nominale':'800 W','Format et normes':'ATX12V v2.3 / SSI EPS12V v2.92','Certification et rendement':'80 PLUS Bronze /85 %','Dimensions (largeur × hauteur × profondeur)':'150 × 86 × 165 mm','Rail +12 V combiné':'773 W pour +12V1/+12V2/+12V3/+12V4','Rails +3,3 V/+5 V combinés':'175 W','Rails individuels':'+3,3V 30A ; +5V 30A ; +12V1 20A ; +12V2 25A ; +12V3 20A ; +12V4 25A ; +5Vsb 3A ; -12V 0,8A','Connecteurs':'Carte mère 24+8+4 ; PCIe 4 ×6+2 ; périphériques 5 ; FDD1 ; SATA9','Câbles':'Détachables','Ventilateur':'1 ×120 mm, régulation thermique','Bruit annoncé':'21 dB, protocole non précisé','Garantie locale du marchand':'36 mois','Entrée secteur':'100–240 V /50–60 Hz'}
 make('import-psu-ebe7581f01d2','EVEREST 85PLUS 800',s,rows,{'power':800,'format':'ATX','atx':'ATX12V2.3','efficiency':'80 PLUS Bronze /85 %','depth':165,'width':150,'height':86,'rail12v':'773 W combinés','connectors':rows['Connecteurs'],'fan':'120 mm','warranty':'36 mois, garantie locale du marchand'},patch={'wattage':800,'psuFormat':'ATX','depthMm':165,'widthMm':150,'heightMm':86,'fanSizeMm':120},notes=['Fiche marchande ancienne, non confirmée par une fiche primaire actuelle. Aucun prix ni disponibilité français ne sont créés.'])
 (D/'supplement-products.json').write_text(json.dumps(OUT,ensure_ascii=False,indent=2));print('FSP supplements',len(OUT))
if __name__=='__main__':main()
